-- --------------------------------------------------------------------------
-- The ten real Kabankalan shops, with the menus their owners supplied.
--
-- Demo CONTENT, not schema, like seed-demo-defense.sql: run it in the Supabase
-- dashboard SQL Editor (Dashboard -> SQL Editor -> paste -> Run). Idempotent.
--
-- What it does:
--   1. Archives every other restaurant. Archived, not deleted: past orders,
--      ratings and refunds still point at them, and an archived shop is hidden
--      from customers (0010).
--   2. Adds the ten shops, open, with their logo (served from the admin site,
--      admin/public/images/shops/).
--   3. Adds their menus (644 items) in pesos. A drink sold in several sizes
--      is one item per size. Items printed without a price ("ask server") are
--      left out; whole cakes at Granjeros are pre-order only and left out too.
--
-- Generated: do not hand-edit the item rows. Re-run the generator instead.
-- Undo: unarchive the old shops and set the new ones' archived_at.
-- --------------------------------------------------------------------------

begin;

-- 1. Every other shop is archived and closed ------------------------------
update public.restaurants
   set archived_at = coalesce(archived_at, now()),
       is_open = false
 where id not in ('rst_alonsos', 'rst_avbean', 'rst_cafenoy', 'rst_castanos', 'rst_granjeros', 'rst_hide_and_seek', 'rst_pikons', 'rst_reginas', 'rst_sols', 'rst_tito_tat');

-- 2. The ten shops ----------------------------------------------------------
on conflict (id) do update set
  name        = excluded.name,
  cuisine     = excluded.cuisine,
  city        = excluded.city,
  status      = excluded.status,
  is_open     = excluded.is_open,
  image_url   = excluded.image_url,
  archived_at = null;

-- 3. Their menus ------------------------------------------------------------
on conflict (id) do update set
  restaurant    = excluded.restaurant,
  restaurant_id = excluded.restaurant_id,
  name          = excluded.name,
  category      = excluded.category,
  price         = excluded.price,
  available     = excluded.available;

commit;

-- Check:
--   select id, name, is_open, archived_at is null as listed from public.restaurants order by archived_at nulls first, name;
--   select restaurant, count(*) from public.menu_items where restaurant_id in ('rst_alonsos', 'rst_avbean', 'rst_cafenoy', 'rst_castanos', 'rst_granjeros', 'rst_hide_and_seek', 'rst_pikons', 'rst_reginas', 'rst_sols', 'rst_tito_tat') group by 1 order by 1;
